//! Releases and the version tools through the one path agents and the app share: a part
//! released as revision A then B (ASME letters), its STEP written outside history with its hash
//! in the record, regenerated byte for byte; and versions, history, create_version, restore and
//! compare answering JSON.

use forge_lang::vtools;
use std::path::PathBuf;
use std::process::Command;

const PART: &str = "shared w = 40
properties(part_number: \"BR-1001\", description: \"Bracket\")
sketch plan(on: xy) {
  outline = rect(corner: (0, 0), size: (w, 30))
}
base = extrude(plan, 10)
";

fn project(name: &str) -> PathBuf {
    let d = PathBuf::from(env!("CARGO_TARGET_TMPDIR")).join(format!("release-{name}-{}", std::process::id()));
    std::fs::create_dir_all(&d).unwrap();
    let d = std::fs::canonicalize(d).unwrap();
    let mut h = forge_history::History::turn_on(&d).unwrap();
    h.set_identity("David Bascom", "davidsprojects7@gmail.com")
        .unwrap();
    forge_lang::pins::forget();
    d
}

fn call(tool: &str, args: &[&str]) -> forge_agent::json::Json {
    let a: Vec<String> = args.iter().map(|s| s.to_string()).collect();
    vtools::call(tool, &a, Some("test-agent"))
        .expect("a tool")
        .expect("it answers")
}

#[test]
fn a_part_released_twice_and_regenerated() {
    let d = project("rel");
    let f = d.join("bracket.fg");
    std::fs::write(&f, PART).unwrap();
    let fs = f.to_str().unwrap();
    let a = call("release", &[fs, "First article", "--approver", "Lingyun"]);
    assert_eq!(a.get("revision").and_then(|x| x.str()), Some("A"));
    assert_eq!(a.get("part_number").and_then(|x| x.str()), Some("BR-1001"));
    assert_eq!(a.get("approver").and_then(|x| x.str()), Some("Lingyun"));
    let step = d.join("releases/BR-1001/A/bracket-A.step");
    assert!(step.is_file());
    let text = std::fs::read(&step).unwrap();
    let sha = forge_git::HashKind::Sha256.of(&text).hex();
    assert!(a.to_string().contains(&sha));

    std::fs::write(&f, PART.replace("w = 40", "w = 44")).unwrap();
    let b = call("release", &[fs, "Wider for the new rail"]);
    assert_eq!(b.get("revision").and_then(|x| x.str()), Some("B"));

    let g = call("regenerate_release", &[fs, "A"]);
    assert_eq!(g.get("result").and_then(|x| x.str()), Some("identical"), "{g}");
    assert_eq!(std::fs::read(&step).unwrap(), text);

    let rs = call("releases", &[fs]);
    assert_eq!(rs.to_string().matches("\"revision\"").count(), 2);
    // released versions are named versions too, and exports stay out of history
    let vs = call("versions", &[fs]).to_string();
    assert!(
        vs.contains("bracket rev A") && vs.contains("bracket rev B"),
        "{vs}"
    );
    let files = Command::new("git")
        .arg("-C")
        .arg(&d)
        .args(["ls-files"])
        .output()
        .unwrap();
    let files = String::from_utf8(files.stdout).unwrap();
    assert!(!files.contains("releases/"), "{files}");
    let fsck = Command::new("git")
        .arg("-C")
        .arg(&d)
        .args(["fsck", "--strict", "--no-dangling"])
        .status()
        .unwrap();
    assert!(fsck.success());
}

#[test]
fn the_tools_answer_json() {
    let d = project("tools");
    let f = d.join("block.fg");
    std::fs::write(&f, PART).unwrap();
    let fs = f.to_str().unwrap();
    let v = call("create_version", &[fs, "Plain", "the first block"]);
    assert_eq!(v.get("n").and_then(|x| x.num()), Some(1.0));
    assert_eq!(v.get("agent").and_then(|x| x.str()), Some("test-agent"));
    std::fs::write(&f, PART.replace("w = 40", "w = 50")).unwrap();
    call("create_version", &[fs, "Wide", ""]);
    let h = call("history", &[fs]);
    assert_eq!(h.get("count").and_then(|x| x.num()), Some(2.0));
    let c = call("compare", &[fs, "v1", "v2", "--volume"]);
    let added = c
        .get("volume")
        .and_then(|v| v.get("added_mm3"))
        .and_then(|x| x.num())
        .unwrap();
    assert!((added - 10.0 * 30.0 * 10.0).abs() < 1e-6, "{c}");
    let r = call("restore", &[fs, "v1"]);
    assert!(r.get("restored").and_then(|x| x.str()).unwrap().starts_with("v1"));
    assert_eq!(std::fs::read_to_string(&f).unwrap(), PART);
    assert_eq!(
        call("history", &[fs]).get("count").and_then(|x| x.num()),
        Some(3.0)
    );
    let e = vtools::call("restore", &[fs.to_string(), "v9".into()], None).unwrap();
    assert!(e.is_err());
}
